import {esc} from '../editor/model.js';
import {dispensingData as d} from './dispensing-data.js';
import {icon} from '../../shared/icons.js';
const sourceHref='/case/'+encodeURIComponent(d.source);
const row=(label,value)=>`<div><dt>${label}</dt><dd>${value}</dd></div>`;
const figure=(id,title,caption)=>`<figure class="report-chart"><h3>${title}</h3><div id="${id}"></div><figcaption>${caption}</figcaption></figure>`;
export function comparisonChart(pressure='0.2',kind='diameter'){
 const diameter=kind==='diameter',xs=diameter?d.diameters:d.multipliers,ys=diameter?d.flow[pressure].simulation:d.sensitivity[pressure],baseline=diameter?d.flow[pressure].experiment:null;
 return lineChart({xs,ys,baseline,yMax:diameter?(pressure==='0.2'?.11:.22):(pressure==='0.2'?.21:.42),xLabel:diameter?'出口直径（mm）':'黏度倍率',yLabel:'出胶量（g/s）',seriesLabel:'仿真值',baselineLabel:'实验值 '+baseline?.toFixed(4),formatY:n=>n.toFixed(2)});
}
function lineChart({xs,ys,baseline=null,yMax,xLabel,yLabel,seriesLabel,baselineLabel,formatY=n=>String(n),secondary}){
 const left=62,top=24,w=520,h=230,bottom=top+h,x=n=>left+(n-xs[0])/(xs.at(-1)-xs[0])*w,y=n=>bottom-n/yMax*h;
 const points=ys.flatMap((value,i)=>value===null?[]:[`${x(xs[i])},${y(value)}`]).join(' ');
 return `<svg class="report-plot" viewBox="0 0 620 315" role="img" aria-label="${esc(seriesLabel)}，横轴${xLabel}，纵轴${yLabel}"><text x="${left}" y="13" class="plot-label">${yLabel}</text>${Array.from({length:5},(_,i)=>{const value=yMax*i/4;return `<line x1="${left}" y1="${y(value)}" x2="${left+w}" y2="${y(value)}" class="plot-grid"/><text x="${left-10}" y="${y(value)+4}" text-anchor="end" class="plot-tick">${formatY(value)}</text>`;}).join('')}${xs.map(n=>`<text x="${x(n)}" y="${bottom+21}" text-anchor="middle" class="plot-tick">${n}</text>`).join('')}<text x="${left+w/2}" y="305" text-anchor="middle" class="plot-label">${xLabel}</text>${baseline!==null?`<line x1="${left}" y1="${y(baseline)}" x2="${left+w}" y2="${y(baseline)}" class="plot-experiment"/>`:''}${secondary?`<polyline points="${secondary.map((v,i)=>`${x(xs[i])},${y(v)}`).join(' ')}" class="plot-fit"/>`:''}<polyline points="${points}" class="plot-simulation"/>${ys.map((v,i)=>v===null?'':`<circle cx="${x(xs[i])}" cy="${y(v)}" r="4" class="plot-point"><title>${xs[i]}：${v} ${yLabel.includes('g/s')?'g/s':'mPa·s'}</title></circle>`).join('')}</svg><div class="plot-legend"><span><i></i>${seriesLabel}</span>${baseline!==null?`<span class="legend-experiment"><i></i>${baselineLabel} g/s</span>`:''}${secondary?'<span class="legend-fit"><i></i>Herschel–Bulkley拟合</span>':''}</div>`;
}
function viscosityChart(){const xs=d.viscosity.map(v=>v[0]),ys=d.viscosity.map(v=>v[1]);const f=d.fit;return lineChart({xs,ys,yMax:700,xLabel:'转速（rpm）',yLabel:'黏度（mPa·s）',seriesLabel:'实验测点',formatY:n=>n.toFixed(0),secondary:xs.map(rpm=>(f.yield/(rpm*f.shearFactor)+f.consistency*(rpm*f.shearFactor)**(f.index-1))*1000)});}
export function renderDispensingReport({workflow,run,back,actualInputs=''}){
 const ready=run?.status==='成功'&&run.reportStatus==='已生成';
 return `<main class="dispensing-report page-main" data-ui><header class="report-page-heading"><div><button class="back-link" data-return-editor="${esc(back)}">${icon('chevron')}返回计算建模</button><h1>点胶仿真分析报告</h1><p>${esc(workflow.name)} <span>·</span> ${esc(run?.id||'尚未运行')}</p></div><div class="report-page-actions"><a class="btn" href="${sourceHref}" download="${d.source}">${icon('download')}下载原始报告</a><button class="btn primary" data-print-report>${icon('file')}打印 / 保存 PDF</button></div></header>
 <div class="report-source-banner">${icon('info')}<div><strong>参考报告展示</strong><span>内容依据《${d.source}》及其内嵌拟合数据整理，不代表当前任务新生成的计算结果。</span></div><span class="report-run-state">本次执行：${esc(run?.status||'尚未运行')} · 报告${esc(run?.reportStatus||'等待生成')}</span></div>
 <div class="report-page-tabs" role="tablist" aria-label="报告内容"><button role="tab" aria-selected="true" data-report-tab="report">报告正文</button><button role="tab" aria-selected="false" data-report-tab="logs">执行日志</button><button role="tab" aria-selected="false" data-report-tab="inputs">输入快照</button></div>
 <section data-report-panel="report" role="tabpanel">${!ready?`<div class="report-waiting"><h2>本次报告尚未就绪</h2><p>等待计算与报告生成完成。下方为独立的点胶仿真参考报告。</p></div>`:''}
 <div class="report-reading-layout"><aside class="report-outline" aria-label="报告目录"><strong>报告目录</strong><a href="#report-summary">结果概览</a><a href="#report-geometry">几何与工况</a><a href="#report-viscosity">黏度测试与拟合</a><a href="#report-diameter">出口直径影响</a><a href="#report-sensitivity">黏度敏感性</a><a href="#report-conclusion">结论与适用范围</a><small>源文件 · 3页<br>含内嵌拟合工作表</small></aside><article class="report-body">
 <section id="report-summary" class="report-section"><div class="report-section-title"><h2>结果概览</h2><span>点胶流动仿真</span></div><p class="report-lead">通过黏度测试数据建立流变模型，对比不同出口直径、压力及黏度条件下的出胶量，评估仿真与实验的一致性。</p><div class="report-findings"><div><span>原报告结论中的吻合区间</span><strong>0.48–0.50 <small>mm</small></strong><p>出口直径；需结合不同压力工况分别判断。</p></div><div><span>对比压力</span><strong>0.2 / 0.4 <small>MPa</small></strong><p>实验出胶量分别为0.0494、0.1204 g/s。</p></div><div><span>黏度拟合优度</span><strong>0.99886 <small>R²</small></strong><p>来自内嵌工作表的7个有效测点。</p></div></div><p class="report-footnote">本页结果表使用质量流率（g/s）表示出胶量，未换算为线速度。吻合区间引用原报告结论，原文件未定义统一误差验收阈值。</p></section>
 <section id="report-geometry" class="report-section"><h2>几何与工况</h2><div class="report-geometry"><img src="/assets/reports/dispensing/geometry.png" alt="原报告点胶流道几何，标注入口、出口、流动方向及各段尺寸"><p>原报告第2页 · 实验几何与流动方向，图中基准出口直径0.55 mm。</p></div><dl class="report-facts">${row('材料密度','1.159 g/cm³（1159 kg/m³）')}${row('测试温度','25 °C，恒温水浴')}${row('测试装样量','6.7 mL')}${row('黏度测量转子','SC4-18')}${row('压力工况','0.2 MPa / 0.4 MPa')}${row('出口直径扫描','0.40、0.45、0.48、0.50、0.55 mm')}</dl></section>
 <section id="report-viscosity" class="report-section"><h2>黏度测试与拟合</h2><p>转速由0.5 rpm增加到4.0 rpm时，实验黏度由642.0降至419.3 mPa·s。图中拟合线依据原报告内嵌工作表的参数绘制。</p><div class="report-viscosity-layout">${figure('viscosity-chart','实验黏度与拟合曲线','剪切速率换算系数：1.32 s⁻¹/rpm；实测剪切速率范围0.66–5.28 s⁻¹。')}<div class="report-fit-parameters"><h3>Herschel–Bulkley模型</h3><p class="report-formula">μ = τy / γ̇ + K · γ̇<sup>n−1</sup></p><dl>${row('屈服应力 τy','0.174553 Pa')}${row('稠度系数 K','0.379349 Pa·sⁿ')}${row('流动指数 n','1.005360')}${row('RMSE','2.482 mPa·s')}</dl><details><summary>查看7组实验测点</summary><table><thead><tr><th>转速 rpm</th><th>黏度 mPa·s</th></tr></thead><tbody>${d.viscosity.map(([x,y])=>`<tr><td>${x.toFixed(1)}</td><td>${y.toFixed(1)}</td></tr>`).join('')}</tbody></table></details></div></div><p class="report-footnote">拟合参数来自内嵌Workbook1.xlsx缓存数值，未重新拟合。该拟合优度只描述已提供测点，不作为更宽剪切速率范围的验证。</p></section>
 <section id="report-diameter" class="report-section"><div class="report-section-title"><h2>出口直径对出胶量的影响</h2><div class="report-pressure" role="group" aria-label="出口直径对比压力"><button data-report-pressure="0.2" aria-pressed="true">0.2 MPa</button><button data-report-pressure="0.4" aria-pressed="false">0.4 MPa</button></div></div>${figure('diameter-chart','仿真与实验对比','点为原报告仿真数据，虚线为相应压力下的实验出胶量。0.4 MPa、0.40 mm未提供仿真值，不作补齐。')}<div class="report-table-wrap"><table class="report-data-table"><caption>出口直径扫描结果 · 出胶量单位g/s</caption><thead><tr><th>压力 MPa</th><th>实验值</th>${d.diameters.map(n=>`<th>φ${n.toFixed(2)} mm</th>`).join('')}</tr></thead><tbody>${Object.entries(d.flow).map(([pressure,v])=>`<tr data-pressure-row="${pressure}"><th>${pressure}</th><td class="experiment-value">${v.experiment.toFixed(4)}</td>${v.simulation.map((n,i)=>`<td class="${[.48,.5].includes(d.diameters[i])?'report-reference-range':''}">${n===null?'—':n.toFixed(4)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="report-footnote">淡紫列对应原报告结论提及的直径范围，不表示所有压力下误差最小。</p></section>
 <section id="report-sensitivity" class="report-section"><div class="report-section-title"><h2>黏度敏感性分析</h2><div class="report-pressure" role="group" aria-label="黏度敏感性对比压力"><button data-sensitivity-pressure="0.2" aria-pressed="true">0.2 MPa</button><button data-sensitivity-pressure="0.4" aria-pressed="false">0.4 MPa</button></div></div><p>保持出口直径0.55 mm，按原始拟合黏度的0.5、0.7、1.0、1.1、1.3倍进行对比。在这组输入中，黏度越高，出胶量越低。</p>${figure('sensitivity-chart','不同黏度倍率下的出胶量','原始拟合黏度为1.0倍基线。图中仅连接已有仿真数据点。')}<div class="report-table-wrap"><table class="report-data-table"><caption>黏度倍率扫描结果 · 出胶量单位g/s</caption><thead><tr><th>压力 MPa</th>${d.multipliers.map(x=>`<th>${x.toFixed(1)}×${x===1?' 基线':''}</th>`).join('')}</tr></thead><tbody>${Object.entries(d.sensitivity).map(([p,values])=>`<tr><th>${p}</th>${values.map(x=>`<td>${x.toFixed(4)}</td>`).join('')}</tr>`).join('')}</tbody></table></div></section>
 <section id="report-conclusion" class="report-section"><h2>结论与适用范围</h2><ol class="report-conclusions"><li>原报告认为，已提供的仿真输入条件可支持本次点胶仿真，后续首次提供实验参数时可参考该输入组织方式。</li><li>依据本次输入，可分析点胶出胶量及其随压力、出口直径和黏度的变化。</li><li>原报告认为出口直径0.48–0.50 mm时仿真与实验较为吻合，具体数值以两组压力下的对比表为准。</li><li>当前结论限定于文件中的材料、几何、测试条件和仿真数据，尚未给出跨工况的统一误差标准。</li></ol><footer class="report-provenance"><strong>内容来源</strong><span>第1页：黏度测试、密度、仿真目的及内嵌拟合数据；第2页：实验几何；第3页：出口直径、黏度敏感性及结论。</span><a href="${sourceHref}" download="${d.source}">下载《${d.source}》</a></footer></section>
 </article></div></section>
 <section data-report-panel="logs" role="tabpanel" hidden class="report-support-panel"><h2>本次执行日志</h2><p>下方日志属于当前任务，与参考PPT中的实验数据分开保留。</p><pre>${esc(run?.logs?.join('\n')||'暂无新增执行日志。')}</pre></section>
 <section data-report-panel="inputs" role="tabpanel" hidden class="report-support-panel"><h2>本次执行输入快照</h2><p>当前任务提交时的只读输入；不与参考报告中的工况自动绑定。</p><pre>${esc(JSON.stringify(run?.snapshot||{},null,2))}</pre>${actualInputs}</section></main>`;
}
export function mountDispensingReport(root){
 const draw=(id,html)=>{root.querySelector('#'+id).innerHTML=html;};draw('viscosity-chart',viscosityChart());draw('diameter-chart',comparisonChart());draw('sensitivity-chart',comparisonChart('0.2','viscosity'));
 const click=e=>{const anchor=e.target.closest('.report-outline a');if(anchor){e.preventDefault();root.querySelector(anchor.hash)?.scrollIntoView({behavior:'smooth',block:'start'});history.replaceState(null,'',anchor.hash);root.querySelectorAll('.report-outline a').forEach(a=>a.setAttribute('aria-current',String(a===anchor)));return;}const tab=e.target.closest('[data-report-tab]');if(tab){root.querySelectorAll('[data-report-tab]').forEach(b=>b.setAttribute('aria-selected',String(b===tab)));root.querySelectorAll('[data-report-panel]').forEach(p=>p.hidden=p.dataset.reportPanel!==tab.dataset.reportTab);}
 const pressure=e.target.closest('[data-report-pressure],[data-sensitivity-pressure]');if(pressure){const sensitivity=pressure.hasAttribute('data-sensitivity-pressure'),value=sensitivity?pressure.dataset.sensitivityPressure:pressure.dataset.reportPressure;pressure.parentElement.querySelectorAll('button').forEach(b=>b.setAttribute('aria-pressed',String(b===pressure)));draw(sensitivity?'sensitivity-chart':'diameter-chart',comparisonChart(value,sensitivity?'viscosity':'diameter'));}
 if(e.target.closest('[data-print-report]')){root.querySelector('[data-report-tab="report"]').click();window.print();}
 };root.addEventListener('click',click);return()=>root.removeEventListener('click',click);
}
